<?php
use Modules\Core\Models\User;use Modules\Finance\Models\AccountMapping;use Modules\Finance\Models\ArInvoice;use Modules\Finance\Models\ArPayment;use Modules\Finance\Models\BankAccount;use Modules\Finance\Models\BankStatementImport;use Modules\Finance\Services\BankReconciliationService;use Modules\MasterData\Models\ChartOfAccount;use Modules\MasterData\Models\Customer;use Modules\Sales\Models\SalesOrder;
function bankFixture():array{$u=User::factory()->create(['company_id'=>1]);$coa=ChartOfAccount::create(['company_id'=>1,'code'=>'BANK-'.uniqid(),'name'=>'Bank','type'=>'ASSET','normal_balance'=>'DEBIT']);$a=BankAccount::create(['company_id'=>1,'code'=>'B-'.uniqid(),'name'=>'Operating','bank_name'=>'Bank Test','coa_id'=>$coa->id,'created_by'=>$u->id]);return[$u,$a,$coa];}function importBank(BankReconciliationService$s,BankAccount$a,User$u):BankStatementImport{return$s->import($a,['statement_no'=>'ST-'.uniqid(),'period_start'=>'2026-08-01','period_end'=>'2026-08-31','opening_balance'=>1000,'closing_balance'=>1050],[['transaction_date'=>'2026-08-10','direction'=>'CREDIT','amount'=>100,'reference_no'=>'IN-1'],['transaction_date'=>'2026-08-11','direction'=>'DEBIT','amount'=>50,'reference_no'=>'FEE-1']],$u);}function arPayment(User$u,float$amount):ArPayment{$c=Customer::create(['company_id'=>1,'code'=>'C-'.uniqid(),'name'=>'Buyer']);$so=SalesOrder::create(['company_id'=>1,'doc_no'=>'SO-'.uniqid(),'customer_id'=>$c->id,'order_date'=>'2026-08-01','status'=>'CLOSED','created_by'=>$u->id]);$i=ArInvoice::create(['company_id'=>1,'doc_no'=>'AR-'.uniqid(),'customer_id'=>$c->id,'sales_order_id'=>$so->id,'invoice_date'=>'2026-08-01','exchange_rate'=>1,'subtotal_amount'=>$amount,'total_amount'=>$amount,'base_amount'=>$amount,'finance_finalized_at'=>now(),'paid_amount'=>$amount,'status'=>'PAID','created_by'=>$u->id]);return ArPayment::create(['company_id'=>1,'doc_no'=>'PAY-'.uniqid(),'ar_invoice_id'=>$i->id,'payment_date'=>'2026-08-10','exchange_rate'=>1,'amount'=>$amount,'base_amount'=>$amount,'created_by'=>$u->id]);}
it('mengimpor statement balance dan menolak fingerprint duplikat',function(){[$u,$a]=bankFixture();$s=app(BankReconciliationService::class);$first=importBank($s,$a,$u);expect($first->lines)->toHaveCount(2)->and($first->status)->toBe('IMPORTED');$s->import($a,['statement_no'=>'OTHER','period_start'=>'2026-08-01','period_end'=>'2026-08-31','opening_balance'=>0,'closing_balance'=>100],[['transaction_date'=>'2026-08-10','direction'=>'CREDIT','amount'=>100,'reference_no'=>'IN-1']],$u);})->throws(RuntimeException::class,'Duplicate');
it('mendukung partial many-to-one payment matching dan approval lock',function(){[$u,$a]=bankFixture();$s=app(BankReconciliationService::class);$st=importBank($s,$a,$u);$credit=$st->lines->firstWhere('direction','CREDIT');$p1=arPayment($u,60);$p2=arPayment($u,40);$s->match($credit,'AR_PAYMENT',$p1->id,60,$u);$matched=$s->match($credit->fresh(),'AR_PAYMENT',$p2->id,40,$u);expect($matched->status)->toBe('MATCHED')->and((float)$matched->matched_amount)->toBe(100.0);$s->ignore($st->lines->firstWhere('direction','DEBIT'),'Non-ledger test item',$u);$done=$s->reconcile($st,$u);expect($done->status)->toBe('RECONCILED')->and($done->reconciled_at)->not->toBeNull();$s->match($credit->fresh(),'AR_PAYMENT',$p1->id,1,$u);})->throws(RuntimeException::class,'terkunci');
it('bank fee membuat jurnal dan menyelesaikan debit line',function(){[$u,$a,$bank]=bankFixture();$expense=ChartOfAccount::create(['company_id'=>1,'code'=>'FEE-'.uniqid(),'name'=>'Bank Fee','type'=>'EXPENSE','normal_balance'=>'DEBIT']);AccountMapping::create(['company_id'=>1,'event'=>'BANK_FEE','debit_account_id'=>$expense->id,'credit_account_id'=>$bank->id]);$s=app(BankReconciliationService::class);$st=importBank($s,$a,$u);$debit=$st->lines->firstWhere('direction','DEBIT');$done=$s->bankFee($debit,50,$u);expect($done->status)->toBe('MATCHED')->and($done->matches[0]->source_type)->toBe('BANK_FEE');});
